// Access all input items
const allItems = $input.all();

// Debug: Log the structure to see what we're working with
console.log('All items:', JSON.stringify(allItems, null, 2));

// Try different possible locations for the output
let rawOutput;

if (allItems[0]?.json?.output) {
  rawOutput = allItems[0].json.output;
} else if (allItems[0]?.output) {
  rawOutput = allItems[0].output;
} else if (typeof allItems[0] === 'string') {
  rawOutput = allItems[0];
} else if (allItems[0]?.json) {
  // Maybe the whole json object is the output
  rawOutput = JSON.stringify(allItems[0].json);
} else {
  throw new Error('Could not find output data. Structure: ' + JSON.stringify(allItems[0]));
}

// Extract JSON by finding the first [ and last ]
const startIndex = rawOutput.indexOf('[');
const endIndex = rawOutput.lastIndexOf(']');

if (startIndex === -1 || endIndex === -1) {
  throw new Error('Could not find JSON array in output');
}

// Extract just the JSON array portion
const jsonString = rawOutput.substring(startIndex, endIndex + 1);

// Parse the JSON string
const jobs = JSON.parse(jsonString);

// Map and clean job data for MongoDB
return jobs.map(job => ({
  json: {
    title: job.title,
    company: job.company || "Unknown",
    description: job.description || "",
    skills: job.skills || [],
    location: job.location || "Unknown",
    url: job.url,
    postedAt: job.postedAt
      ? new Date(job.postedAt)
      : new Date(),
    source: "JSearch"
  }
}));

